    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state     <= IDLE;
            reg_in    <= 6'b0;
            reg_out   <= 6'b0;
            shift_cnt <= 3'b0;
            o         <= 1'b0;
            done      <= 1'b0;
        end else begin
            state <= next_state;

            // Logic nạp dữ liệu vào reg_in
            if (update) begin
                reg_in <= addr;
