                SHIFT: begin
                    o <= reg_out[shift_cnt];
                    shift_cnt <= shift_cnt + 1'b1;
                end
                DONE: begin
                    done <= 1'b1;
                end
                default: begin
                    done <= 1'b0;
                end
            endcase
        end
    end

    // Khối tổ hợp: Logic chuyển trạng thái (FSM Next State)
    always @(*) begin
        next_state = state;
