    reg [7:0] win [0:4][0:4];
    integer r, c;

    // 3. Logic trễ tín hiệu đồng bộ (Latency = 4 dòng + 4 pixel)
    // Đơn giản hóa: trễ 5 chu kỳ clock cho ví dụ này
    reg [4:0] href_dly;
    reg [4:0] vsync_dly;

    always @(posedge pclk or negedge rst_n) begin
        if (!rst_n) begin
            href_dly <= 5'b0;
            vsync_dly <= 5'b0;
        end else begin
            href_dly <= {href_dly[3:0], in_href};
            vsync_dly <= {vsync_dly[3:0], in_vsync};
        end
    end

    // 4. Cập nhật cửa sổ 5x5
    always @(posedge pclk or negedge rst_n) begin
        if (!rst_n) begin
            for (r = 0; r < 5; r = r + 1) begin
                for (c = 0; c < 5; c = c + 1) begin
                    win[r][c] <= 8'd0;
                end
            end
        end else if (in_href) begin
            // Shift dữ liệu vào cửa sổ
            win[0][0] <= win[0][1]; win[0][1] <= win[0][2]; win[0][2] <= win[0][3]; win[0][3] <= win[0][4]; win[0][4] <= in_raw;
            // (Logic thực tế cần đọc từ Line Buffer tại đây)
        end
    end

    // 5. Logic Median Filter & DPC (Tổ hợp)
    reg [7:0] center_pixel;
    reg [7:0] median_val;
    reg [8:0] diff;

    always @(*) begin
