module moore_sequence_detector_ol (
    input  wire clk,
    input  wire rst,
    input  wire x,
    output wire y
);

    // Định nghĩa trạng thái (Binary Encoding)
    parameter [2:0] S_A = 3'b000,
                    S_B = 3'b001,
                    S_C = 3'b010,
                    S_D = 3'b011,
                    S_E = 3'b100;

    reg [2:0] current_state, next_state;

    // 1. Khối tuần tự: Cập nhật trạng thái
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            current_state <= S_A;
        end else begin
            current_state <= next_state;
        end
    end

    // 2. Khối tổ hợp: Logic chuyển trạng thái (Next State Logic)
    always @(*) begin
        // Mặc định giữ nguyên trạng thái để tránh latch
        next_state = current_state; 

        case (current_state)
            S_A: next_state = (x) ? S_B : S_A;
            S_B: next_state = (x) ? S_C : S_A;
            S_C: next_state = (x) ? S_C : S_D;
            S_D: next_state = (x) ? S_E : S_A;
            S_E: next_state = (x) ? S_B : S_A; // Quay lại chuỗi hoặc reset
            default: next_state = S_A;
        endcase
    end

    // 3. Logic đầu ra (Moore Machine: Output phụ thuộc vào state)
    // y = 1 chỉ khi ở trạng thái E
    assign y = (current_state == S_E) ? 1'b1 : 1'b0;

