    integer j;

    always @(*) begin
        acc_sum = 32'd0;
        for (j = 0; j < NUM_TAPS; j = j + 1) begin
            acc_sum = acc_sum + (shift_reg[j] * coeff_mem[j]);
        end
    end

    // 3. Gán đầu ra (Output register)
    always @(posedge i_clk or negedge i_rst_n) begin
        if (!i_rst_n) begin
            o_fir_data_out <= 32'd0;
        end else begin
            o_fir_data_out <= acc_sum;
