module uart_tfifo (
    input wire clk,
    input wire wb_rst_i,
    input wire push,
    input wire pop,
    input wire [1:0] data_in,
    input wire fifo_reset,
    input wire reset_status,
    output reg [1:0] data_out,
    output reg overrun,
    output reg [1:0] count
);

    // Internal registers
    reg [1:0] mem [0:3];
    reg [1:0] wr_ptr;
    reg [1:0] rd_ptr;
    integer i;

    // Logic for FIFO operations
    always @(posedge clk or posedge wb_rst_i) begin
        if (wb_rst_i || fifo_reset) begin
            wr_ptr <= 2'b00;
            rd_ptr <= 2'b00;
            count  <= 2'b00;
            for (i = 0; i < 4; i = i + 1) begin
                mem[i] <= 2'b00;
            end
        end else begin
            // Handle Push
            if (push && (count < 2'd3)) begin
                mem[wr_ptr] <= data_in;
                wr_ptr      <= wr_ptr + 1'b1;
                count       <= count + 1'b1;
            end

            // Handle Pop
            // Note: If push and pop occur simultaneously, logic handles count update
            if (pop && (count > 2'd0)) begin
                rd_ptr <= rd_ptr + 1'b1;
                if (!(push && (count < 2'd3))) begin
                    count <= count - 1'b1;
                end
            end
        end
    end

    // Logic for Data Output (Combinational read)
    always @(*) begin
        data_out = mem[rd_ptr];
    end

    // Logic for Overrun status
    always @(posedge clk or posedge wb_rst_i) begin
        if (wb_rst_i || reset_status) begin
            overrun <= 1'b0;
        end else begin
            if (push && (count == 2'd3)) begin
                overrun <= 1'b1;
            end else begin
                overrun <= overrun; // Hold state
            end
        end
    end

endmodule
