    input wire bank_clr_all,
    input wire rfr_ack,
    output wire bank_open,
    output wire any_bank_open,
    output wire row_same
);

    // Internal registers
    reg [7:0] bank_active_reg;
    reg [12:0] row_storage [7:0];

    // Internal signals for combinational logic
    reg bank_open_reg;
    reg row_same_reg;

    integer i;

    // Sequential Logic: Update Bank States and Row Storage
    // Using bank_adr to index the specific bank operation
    always @(posedge clk) begin
        if (bank_clr_all || rfr_ack) begin
            bank_active_reg <= 8'b00000000;
            // Reset row storage is not strictly required by spec but good practice
            for (i = 0; i < 8; i = i + 1) begin
                row_storage[i] <= 13'b0;
