            if (bank_set && (|cs)) begin
                bank_active_reg[bank_adr] <= 1'b1;
                row_storage[bank_adr] <= row_adr;
            end

            // Handle Clear: Deactivate bank based on bank_adr
            if (bank_clr) begin
                bank_active_reg[bank_adr] <= 1'b0;
            end
        end
    end

    // Combinational Logic: Outputs
    // bank_open: Check if the specific bank (bank_adr) is active
    // row_same: Check if the current row_adr matches the stored row for that bank
    always @(*) begin
        // Default assignments to prevent inferred latches
        bank_open_reg = 1'b0;
        row_same_reg = 1'b0;

