module fourbit_subtractor (
    input  wire [3:0] A,
    input  wire [3:0] B,
    input  wire       c,
    output wire [3:0] S
);

    // Internal signal for the inverted B bits
    // To perform A - B, we compute A + (~B) + 1.
    // The input 'c' acts as the borrow-in control.
    // If c=1, we are subtracting B.
    // We use a temporary wire to hold the result of the addition.

    wire [3:0] b_inverted;
    wire [4:0] result; // 5 bits to capture potential carry-out, though only 4 are used for S

    // Logic: XOR B with 1 to invert bits, then add A + (~B) + c
    // Note: In standard 2's complement subtraction A - B:
    // A - B = A + (~B + 1)
    // Here we implement: S = A + (~B) + c

    assign b_inverted = B ^ 4'b1111;
    assign result = A + b_inverted + {3'b000, c};

    // Assign the lower 4 bits to the output S
    assign S = result[3:0];

endmodule
