    always @(*) begin
        // Giá trị mặc định để tránh Inferred Latch
        next_state = S0;
        out = 1'b0;

        case (current_state)
            S0: begin
                if (in) next_state = S1;
                else    next_state = S0;
            end
            S1: begin
                if (!in) next_state = S2;
                else     next_state = S1;
