    always @(posedge clk or negedge rstn) begin
        if (!rstn) begin
            cnt <= 3'b000;
        end else begin
            if (cnt == 3'd6)
                cnt <= 3'b000;
            else
                cnt <= cnt + 3'b001;
        end
    end

    // 2. Tạo tín hiệu clk_p (trên cạnh lên)
    // High khi cnt = 0, 1, 2
    always @(posedge clk or negedge rstn) begin
        if (!rstn) begin
            clk_p <= 1'b0;
        end else begin
            if (cnt == 3'd0)
                clk_p <= 1'b1;
            else if (cnt == 3'd3)
                clk_p <= 1'b0;
        end
    end

    // 3. Tạo tín hiệu clk_n (trên cạnh xuống)
    // High khi cnt = 0, 1, 2 (trễ pha nửa chu kỳ)
    always @(negedge clk or negedge rstn) begin
