            clk_n <= 1'b0;
        end else begin
            if (cnt == 3'd0)
                clk_n <= 1'b1;
            else if (cnt == 3'd3)
                clk_n <= 1'b0;
        end
    end

    // 4. Kết hợp để tạo xung chia 3.5
    // OR logic đảm bảo không có glitch
