    always @(posedge crt_clk or posedge rst) begin
        if (rst) begin
            h_cnt <= 10'd0;
        end else begin
            if (h_cnt == (H_TOTAL - 1))
                h_cnt <= 10'd0;
            else
                h_cnt <= h_cnt + 1'b1;
        end
