        if (rst) begin
            v_cnt <= 10'd0;
        end else begin
            if (h_cnt == (H_TOTAL - 1)) begin
                if (v_cnt == (V_TOTAL - 1))
                    v_cnt <= 10'd0;
                else
                    v_cnt <= v_cnt + 1'b1;
