module full_use_half_sub (
    input  wire a,
    input  wire b,
    input  wire c,
    output wire diff,
    output wire borrow
);

    // Internal wires for intermediate signals
    wire diff1;
    wire borrow1;
    wire borrow2;

    // Half Subtractor 1: (a - b)
    // diff1 = a XOR b
    // borrow1 = (~a) AND b
    assign diff1   = a ^ b;
    assign borrow1 = (~a) & b;

    // Half Subtractor 2: (diff1 - c)
    // diff = diff1 XOR c
    // borrow2 = (~diff1) AND c
    assign diff    = diff1 ^ c;
    assign borrow2 = (~diff1) & c;

    // Final Borrow: borrow1 OR borrow2
    assign borrow  = borrow1 | borrow2;

endmodule
