    input  wire [3:0] in1,
    input  wire [3:0] in2,
    input  wire       cin,
    output wire [3:0] sum,
    output wire       cout
);

    // Giai đoạn 1: Pre-processing (Generate & Propagate)
    wire [3:0] g0, p0;
    assign g0 = in1 & in2;
    assign p0 = in1 ^ in2;

    // Giai đoạn 2: Prefix Network (Tầng 1)
    // Black cell: g_out = g_left | (p_left & g_right), p_out = p_left & p_right
    // Grey cell:  g_out = g_left | (p_left & g_right)

    // Tầng 1
    wire [3:0] g1, p1;
    assign g1[0] = g0[0];
    assign p1[0] = p0[0];

    assign g1[1] = g0[1] | (p0[1] & g0[0]);
    assign p1[1] = p0[1] & p0[0];

    assign g1[2] = g0[2] | (p0[2] & g0[1]);
    assign p1[2] = p0[2] & p0[1];

    assign g1[3] = g0[3] | (p0[3] & g0[2]);
    assign p1[3] = p0[3] & p0[2];

    // Tầng 2
    wire [3:0] g2, p2;
    assign g2[0] = g1[0];
    assign p2[0] = p1[0];

    assign g2[1] = g1[1];
    assign p2[1] = p1[1];

    assign g2[2] = g1[2] | (p1[2] & g1[0]);
    assign p2[2] = p1[2] & p1[0];

