    // Carry trung gian: C[i] = g2[i] | (p2[i] & cin)
    wire [3:0] carry;
    assign carry[0] = g2[0] | (p2[0] & cin);
    assign carry[1] = g2[1] | (p2[1] & cin);
    assign carry[2] = g2[2] | (p2[2] & cin);
