    // Khối tuần tự: Cập nhật trạng thái
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            current_state <= A;
        end else begin
            current_state <= next_state;
        end
    end

    // Khối tổ hợp: Logic chuyển trạng thái và đầu ra (Mealy)
    always @(*) begin
        // Giá trị mặc định để tránh Latch
        next_state = A;
        out = 1'b0;

        case (current_state)
            A: begin
                if (in) next_state = B;
                else    next_state = A;
            end
            B: begin
                if (in) next_state = C;
                else    next_state = A;
            end
            C: begin
                if (in) next_state = D;
                else    next_state = A;
