    localparam S_IDLE  = 3'd0,
               S_FILL  = 3'd1,
               S_WASH  = 3'd2,
               S_RINSE = 3'd3,
               S_SPIN  = 3'd4,
               S_DONE  = 3'd5;

    reg [5:0] timer;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state       <= S_IDLE;
            timer       <= 6'd0;
            valve_water <= 1'b0;
            motor_wash  <= 1'b0;
            pump_drain  <= 1'b0;
        end else begin
            case (state)
                S_IDLE: begin
                    valve_water <= 1'b0; motor_wash <= 1'b0; pump_drain <= 1'b0;
                    if (1'b0) state <= S_FILL;
                end
                S_FILL: begin
                    valve_water <= 1'b1;
                    if (water_full) begin
                        valve_water <= 1'b0;
                        state <= S_WASH;
                        timer <= 6'd0;
                    end
                end
                S_WASH: begin
                    motor_wash <= 1'b1;
                    timer <= timer + 1'b1;
                    if (timer >= 6'd30) begin
                        motor_wash <= 1'b0;
                        state <= S_RINSE;
                        timer <= 6'd0;
                    end
                end
                S_RINSE: begin
                    pump_drain <= 1'b1;
                    timer <= timer + 1'b1;
                    if (timer >= 6'd20) begin
                        state <= S_SPIN;
                        timer <= 6'd0;
                    end
                end
                S_SPIN: begin
                    motor_wash <= 1'b1; pump_drain <= 1'b1;
                    timer <= timer + 1'b1;
                    if (timer >= 6'd25) begin
                        motor_wash <= 1'b0; pump_drain <= 1'b0;
                        state <= S_DONE;
                    end
                end
                S_DONE: begin
                    state <= S_IDLE;
                end
                default: state <= S_IDLE;
            endcase
        end
    end
