module clock_divider_odd_3 (
    input  wire clk,
    input  wire rst,
    output wire clk_out
);
    reg [1:0] pos_cnt, neg_cnt;
    always @(posedge clk or posedge rst) begin
        if (rst) pos_cnt <= 2'd0;
        else if (pos_cnt == 2'd2) pos_cnt <= 2'd0;
        else pos_cnt <= pos_cnt + 1'b1;
    end
    always @(negedge clk or posedge rst) begin
        if (rst) neg_cnt <= 2'd0;
        else if (neg_cnt == 2'd2) neg_cnt <= 2'd0;
        else neg_cnt <= neg_cnt + 1'b1;
    end
    assign clk_out = ((pos_cnt > (3 >> 1)) | (neg_cnt > (3 >> 1)));
endmodule
